-- Run only after checking the existing tables. Existing tables are not rebuilt by IF NOT EXISTS.
create table if not exists public.record_submissions(id bigint generated by default as identity primary key,player_name text not null,level_name text not null,progress integer not null check(progress between 1 and 100),attempts integer,video_url text not null,notes text,status text not null default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz not null default now());
create table if not exists public.level_submissions(id bigint generated by default as identity primary key,level_name text not null,level_id text not null,video_url text not null,submitter_name text,difficulty text,notes text,status text not null default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz not null default now());
alter table public.record_submissions enable row level security; alter table public.level_submissions enable row level security;
grant select,insert,update on public.record_submissions to anon,authenticated; grant select,insert,update on public.level_submissions to anon,authenticated; grant usage,select on all sequences in schema public to anon,authenticated;
drop policy if exists "public can submit records" on public.record_submissions; create policy "public can submit records" on public.record_submissions for insert to anon,authenticated with check(status='pending');
drop policy if exists "public can read approved records" on public.record_submissions; create policy "public can read approved records" on public.record_submissions for select to anon,authenticated using(status='approved');
drop policy if exists "creator can review records" on public.record_submissions; create policy "creator can review records" on public.record_submissions for all to authenticated using((auth.jwt()->>'email')='CREATOR_EMAIL_HERE') with check((auth.jwt()->>'email')='CREATOR_EMAIL_HERE');
drop policy if exists "public can suggest levels" on public.level_submissions; create policy "public can suggest levels" on public.level_submissions for insert to anon,authenticated with check(status='pending');
drop policy if exists "creator can review levels" on public.level_submissions; create policy "creator can review levels" on public.level_submissions for all to authenticated using((auth.jwt()->>'email')='CREATOR_EMAIL_HERE') with check((auth.jwt()->>'email')='CREATOR_EMAIL_HERE');
-- Replace CREATOR_EMAIL_HERE with the creator's exact Supabase login email in both policies.
